// Compute returns the totals of an invoice: the subtotal of its lines, then the coupon on the subtotal,
// then the credit, then tax on what remains. Amounts never go below zero.
func Compute(inv store.Invoice) Totals {
	var subtotal int64
	for _, l := range inv.Lines {
		subtotal += int64(l.Quantity) * l.UnitCents
	}
	coupon := divRoundHalfUp(subtotal*int64(inv.CouponPercent), 100)
	discounted := max(subtotal-coupon-inv.CreditCents, 0)
	tax := divRoundHalfUp(discounted*int64(inv.TaxRateBP), 10000)
	return Totals{SubtotalCents: subtotal, DiscountCents: subtotal - discounted, TaxCents: tax, TotalCents: discounted + tax}
}

// divRoundHalfUp returns num/den rounded half up to a whole number. num and den are non-negative.
func divRoundHalfUp(num, den int64) int64 {
	return (num + den/2) / den
}

